(()=>{
 const seatData={'papa-2':{status:'empty'},'papa-bar4':{status:'occupied',orderNo:'1032',partySize:4},'outdoor-1':{status:'held',orderNo:'1027'},'outdoor-2':{status:'empty'},'outdoor-3':{status:'reserved',reservationPartySize:3},'outdoor-4':{status:'empty'},'annex-1':{status:'occupied',orderNo:'1021'},'annex-2':{status:'reserved',reservationPartySize:2},'annex-3':{status:'held',orderNo:'1019'},'annex-4':{status:'empty'},'room-1':{status:'empty'},'room-2':{status:'occupied',orderNo:'1016'},'room-3':{status:'empty'}};let seatListener=null,seatTransactionCount=0,seatWriteCount=0;
 const saved=()=>{try{return JSON.parse(localStorage.getItem('seatLayoutFixture')||'null')}catch{return null}};
 const writeCount=()=>Number(localStorage.getItem('seatLayoutFixtureWriteCount')||0);
 let layoutListener=null;
 const snapshot=records=>({docs:Object.entries(records).map(([id,data])=>({id,data:()=>data})),forEach(callback){Object.entries(records).forEach(([id,data])=>callback({id,data:()=>data}))}});
 const layoutSnapshot=()=>{const data=saved();return {exists:Boolean(data),data:()=>data}};
 const notify=()=>layoutListener?.(layoutSnapshot());
 addEventListener('storage',event=>{if(event.key==='seatLayoutFixture')notify()});
 const layoutRef={onSnapshot(success){layoutListener=success;success(layoutSnapshot());return()=>{layoutListener=null}}};
 const emitSeats=()=>seatListener?.(snapshot(seatData));
 const db={collection(name){return {doc(id){if(name==='adminSettings')return layoutRef;return {name,id,set:async()=>{},collection:child=>({doc:childId=>({name:`${name}/${id}/${child}`,id:childId})})}},onSnapshot(success){if(name==='seats'){seatListener=success;success(snapshot(seatData));return()=>{seatListener=null}}success(snapshot({}));return()=>{};}}},async runTransaction(callback){let pending=null;const result=await callback({get:async ref=>ref?.name==='seats'?{exists:Boolean(seatData[ref.id]),data:()=>({...seatData[ref.id]})}:ref===layoutRef?layoutSnapshot():{exists:false,data:()=>({})},set(ref,data){if(ref?.name==='seats'){pending={ref,data};return}const stored={...data,updatedAt:{seconds:Math.floor(Date.now()/1000)}};localStorage.setItem('seatLayoutFixtureWriteCount',String(writeCount()+1));localStorage.setItem('seatLayoutFixture',JSON.stringify(stored));queueMicrotask(notify)}});if(pending){seatTransactionCount++;seatWriteCount++;seatData[pending.ref.id]={...seatData[pending.ref.id],...pending.data};queueMicrotask(emitSeats)}return result}};
 window.db=db;window.firebase={auth(){return {currentUser:{uid:'fixture-admin'},onAuthStateChanged(callback){callback({uid:'fixture-admin',getIdTokenResult:async()=>({claims:{admin:true}})});return()=>{}},signOut:async()=>{}}},firestore:{FieldValue:{serverTimestamp:()=>({fixtureTimestamp:true})},Timestamp:{fromDate:date=>date}}};
 window.__seatLayoutFixture={db,seatData,get writeCount(){return writeCount()},get seatTransactionCount(){return seatTransactionCount},get seatWriteCount(){return seatWriteCount},setSeat(id,data){seatData[id]={...data};emitSeats()},server(){return saved()},setServer(data){localStorage.setItem('seatLayoutFixture',JSON.stringify(data));notify()},clear(){localStorage.removeItem('seatLayoutFixture');localStorage.removeItem('seatLayoutFixtureWriteCount')}};
})();
